import Page10 from './pages/Page10.jsx';
import Page11 from './pages/Page11.jsx';
import Page12 from './pages/Page12.jsx';
import Page13 from './pages/Page13.jsx';
import Page14 from './pages/Page14.jsx';
import Page15 from './pages/Page15.jsx';
const pages={"demo-megastore-1":Page0,"demo-megastore-1-about":Page1,"demo-megastore-1-account":Page2,"demo-megastore-1-cart-empty":Page3,"demo-megastore-1-cart":Page4,"demo-megastore-1-checkout":Page5,"demo-megastore-1-deals":Page6,"demo-megastore-1-departments":Page7,"demo-megastore-1-help":Page8,"demo-megastore-1-membership":Page9,"demo-megastore-1-order-complete":Page10,"demo-megastore-1-product":Page11,"demo-megastore-1-shop":Page12,"demo-megastore-1-stores":Page13,"demo-megastore-1-track-order":Page14,"demo-megastore-1-weekly-ad":Page15};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-megastore-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-megastore-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
